using SwitchHandover.Core.Services;
try{
 string? Value(string key){var i=Array.IndexOf(args,key);return i>=0&&i+1<args.Length?args[i+1]:null;}
 if(args.Length==0||args.Contains("--help")){Console.WriteLine("SwitchHandover --input file-or-folder [--input archive.zip] --location Site [--location-type Branch|DC|DR|Vendor] [--mgmt-vlan 10] [--excel report.xlsx] [--csv report.csv --csv-kind switches|ports|sfp|allports] [--vsdx topology.vsdx] [--bundle reports.zip] [--no-sfp] [--no-all-ports]. Offline core only; live capture is an explicit desktop action.");return 0;}
 var inputs=new List<string>();for(var i=0;i<args.Length;i++)if(args[i]=="--input"&&i+1<args.Length)inputs.Add(args[++i]);using var cts=new CancellationTokenSource();Console.CancelKeyPress+=(_,e)=>{e.Cancel=true;cts.Cancel();};var options=new AnalysisOptions(Value("--location")??throw new ArgumentException("--location required."),Value("--location-type")??"Branch",Value("--mgmt-vlan"),!args.Contains("--no-sfp"),!args.Contains("--no-all-ports"));var analysis=HandoverAnalysis.FromFiles(inputs,options,token:cts.Token);
 foreach(var pair in new (string,Action<string>)[]{("--excel",(Action<string>)(p=>analysis.ExportExcel(p))),("--csv",p=>analysis.ExportCsv(p,Value("--csv-kind")??"ports")),("--vsdx",analysis.ExportVisio),("--bundle",analysis.ExportBundle)})if(Value(pair.Item1) is {} path){cts.Token.ThrowIfCancellationRequested();pair.Item2(path);}Console.WriteLine($"Handover: {analysis.Switches.Count} inventory rows; {analysis.Ports.Count} neighbor ports; {analysis.Sfps.Count} SFPs; {analysis.Layout.Nodes.Count} topology nodes / {analysis.Layout.Links.Count} physical wires; {analysis.Notes.Count} notes.");return 0;
}catch(OperationCanceledException){Console.Error.WriteLine("Canceled.");return 130;}catch(Exception ex){Console.Error.WriteLine(ex.Message);return 1;}
